const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/payload-size.cjs');
test('encoding determines byte length', () => {
  for (const [text,enc,expected] of [
    ['星河',undefined,6], ['A😀',undefined,5], ['é',undefined,2],
    ['é','latin1',1], ['A😀','utf16le',6], ['星','UTF-8',3],
    ['c0ffee','hex',3], ['AQIDBA==','base64',4], ['',undefined,0]
  ]) assert.equal(app.payloadBytes(text,enc),expected);
});
test('supported aliases and valid base64url strings', () => {
  for (const [text,enc,expected] of [
    ['_w','base64url',1], ['AQIDBA','BASE64URL',4],
    ['A😀','ucs-2',6], ['星','ascii',1], ['😀','latin1',2]
  ]) assert.equal(app.payloadBytes(text,enc),expected);
});
